import{z as l,x as o,o as t,c as C,q as B,j as e,D as a,d as r,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"保证金与清算运营","description":"","frontmatter":{"title":"保证金与清算运营","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-margin-clearing-ops.md","filePath":"quant/qo-margin-clearing-ops.md","lastUpdated":1791063341000}'),i={name:"quant/qo-margin-clearing-ops.md"};function p(m,E,d,_,h,D){const A=o("Mermaid");return t(),C("div",null,[E[2]||(E[2]=B('<h1 id="保证金与清算运营" tabindex="-1">保证金与清算运营 <a class="header-anchor" href="#保证金与清算运营" aria-label="Permalink to &quot;保证金与清算运营&quot;">​</a></h1><div class="epigraph"><p>保证金不是手续费，是按日重估的信用额度；追缴通知到达的时刻，能依靠的只有昨天就算好的预算。</p><footer>—— 据保证金逐日盯市与中央对手方违约瀑布的公开机制整理</footer></div><p><a href="/quant/qo-stockloan-ops">上一课</a>把券变成一条每天要续的供应链；本课管另一条供应链——资金。中央对手方的净额与违约瀑布机制已在<a href="/quant/ccp-default-waterfall">中央对手方与违约瀑布</a>写过，失败交收的状态已在<a href="/quant/settlement-fails">结算周期与失败</a>写过，T+1 对运营窗口的压缩已在<a href="/quant/us-t1-settlement">美国 T+1 结算</a>写过；本课写机构自己的那本账：保证金占用怎么预算、追缴怎么走流程、清算截止怎么守。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略层把保证金当常数或当比例，运营知道它是被 CCP 与券商<strong>每日重估的随机变量</strong>：初始保证金随波动率参数跳变，维持线随持仓市值移动，追缴恰好发生在波动最大、流动性最差的日子。缺口的形态有三：<strong>口径</strong>——期货、场外、融券、回购各有一套保证金逻辑，加总口径没人管，账户层面集中触线；<strong>时点</strong>——资金划款要过托管与银行链路，晚于追缴时限就是违约；<strong>次序</strong>——真到强平时先平什么，没有预写就是现场发挥。不解决这三条，一次全市场的波动率跳升就能把一个本没有方向性亏损的组合打成被动减仓。</p><p><span class="marginnote">「逐日盯市」（mark-to-market）就是每天收盘后按最新市价重算一遍盈亏与占用的制度：赚了当天进账，亏了当天补钱。它让风险每天结清、不攒隔夜雷，代价是坏日子里的补钱要求恰好最急——「追缴通知」就是这么来的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把保证金做成预算科目，四个动作。<strong>占用台账</strong>：逐账户、逐品种记初始与维持保证金，并与券商与 CCP 的日结逐项对平——口径对不上的账户不许开新仓。<strong>情景预测</strong>：保证金参数有公开的变动节奏（定期重估、到期换月、波动率区间切换），用参数日历做压力情景，估下一天的占用 \\(M_{t+1}\\)，而不是拿今天的数外推。<strong>预算与预警带</strong>：\\(\\mathrm{IM}_t+\\mathrm{VM}_t+B_t\\le C_t\\)，占用加缓冲不超过可用资金 \\(C_t\\)；设两道预警线，第一道限开新仓，第二道启动预划款——钱在路上比钱在账上慢，预警线就是给这段路留的。<strong>追缴与强平的预写</strong>：收到通知后的核对、划款、争议路径与责任人固定；强平次序按「对组合功能的伤害最小」预先排好，与<a href="/quant/sl-exit-mechanism">退出机制</a>的分级逻辑同源。</p>',8)),(t(),e(s,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LED%5B%22%E5%8D%A0%E7%94%A8%E5%8F%B0%E8%B4%A6%EF%BC%9A%E9%80%90%E8%B4%A6%E6%88%B7%E9%80%90%E5%93%81%E7%A7%8D%22%5D%20--%3E%20FC%5B%22%E6%83%85%E6%99%AF%E9%A2%84%E6%B5%8B%20M(t%2B1)%22%5D%0A%20%20FC%20--%3E%20BUD%7B%22%E9%A2%84%E7%AE%97%E6%A3%80%E6%9F%A5%22%7D%0A%20%20BUD%20--%3E%7C%22%E7%AC%AC%E4%B8%80%E9%81%93%E9%A2%84%E8%AD%A6%22%7C%20NO%5B%22%E9%99%90%E5%BC%80%E6%96%B0%E4%BB%93%22%5D%0A%20%20BUD%20--%3E%7C%22%E7%AC%AC%E4%BA%8C%E9%81%93%E9%A2%84%E8%AD%A6%22%7C%20WIRE%5B%22%E9%A2%84%E5%88%92%E6%AC%BE%EF%BC%9A%E9%92%B1%E5%85%88%E4%B8%8A%E8%B7%AF%22%5D%0A%20%20BUD%20--%3E%7C%22%E6%AD%A3%E5%B8%B8%22%7C%20RUN%5B%22%E6%8C%81%E7%BB%AD%E8%BF%90%E8%A1%8C%22%5D%0A%20%20CALL%5B%22%E5%88%B8%E5%95%86%E6%88%96%20CCP%20%E8%BF%BD%E7%BC%B4%E9%80%9A%E7%9F%A5%22%5D%20--%3E%20CHK%5B%22%E6%A0%B8%E5%AF%B9%E5%8F%A3%E5%BE%84%E4%B8%8E%E6%98%8E%E7%BB%86%22%5D%0A%20%20CHK%20--%3E%20PAY%7B%22%E6%8C%89%E6%97%B6%E9%99%90%E5%88%92%E6%AC%BE%22%7D%0A%20%20PAY%20--%3E%7C%22%E8%A1%A5%E4%B8%8A%22%7C%20RUN%0A%20%20PAY%20--%3E%7C%22%E8%A1%A5%E4%B8%8D%E4%B8%8A%22%7C%20LIQ%5B%22%E6%8C%89%E9%A2%84%E5%86%99%E6%AC%A1%E5%BA%8F%E5%87%8F%E4%BB%93%22%5D%0A%20%20LIQ%20--%3E%20LED%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么预测必须用情景而不是均值：保证金参数是波动率的阶梯函数，参数跳变的日子恰是追缴与流动性紧张重合的日子——这是逐日盯市的顺周期性，均值外推会在最需要缓冲的那天给出最错的预算。预算不等式里缓冲 \\(B_t\\) 的作用因此不是「多留一点钱」，而是把追缴从「违约事件」降级成「划款动作」：CCP 的瀑布里，会员违约前的每一道防线（保证金、违约瀑布资源）都是公开设计的（<a href="/quant/ccp-default-waterfall">中央对手方与违约瀑布</a>），机构内部同样要有一条自己的瀑布——现金缓冲、可变现抵押、预先批准的减仓次序。清算侧同理：交收失败不是异常态而是常态状态变量，未确认的腿、缺券的交付、外汇未备妥都要当天就出现在对账差异里（<a href="/quant/settlement-fails">结算周期与失败</a>）；回购融资腿的保证金与折扣率是同一条资金链的上游（<a href="/quant/repo-funding">回购市场与融资</a>）。</p>',2)),(t(),e(s,null,{default:a(()=>[n(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%B8%82%E5%9C%BA%E6%B3%A2%E5%8A%A8%E7%8E%87%E8%B7%B3%E5%8D%87%22%5D%20--%3E%20P%5B%22CCP%20%E9%87%8D%E4%BC%B0%E5%8F%82%E6%95%B0%EF%BC%9A%E6%B3%A2%E5%8A%A8%E7%8E%87%E5%8C%BA%E9%97%B4%E5%88%87%E6%8D%A2%22%5D%0A%20%20P%20--%3E%20IM%5B%22%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E8%B0%83%22%5D%0A%20%20V%20--%3E%20MV%5B%22%E6%8C%81%E4%BB%93%E5%B8%82%E5%80%BC%E4%B8%8B%E8%B7%8C%EF%BC%9A%E7%BB%B4%E6%8C%81%E7%BA%BF%E9%80%BC%E8%BF%91%22%5D%0A%20%20IM%20--%3E%20GAP%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E7%BC%BA%E5%8F%A3%E6%89%A9%E5%A4%A7%22%5D%0A%20%20MV%20--%3E%20GAP%0A%20%20V%20--%3E%20LIQ%5B%22%E5%85%A8%E5%B8%82%E5%9C%BA%E9%83%BD%E5%9C%A8%E7%AD%B9%E9%92%B1%EF%BC%9A%E6%B5%81%E5%8A%A8%E6%80%A7%E5%8F%98%E5%B7%AE%22%5D%0A%20%20GAP%20--%3E%20TIGHT%5B%22%E5%88%92%E6%AC%BE%E9%93%BE%E8%B7%AF%E6%8B%A5%E5%A0%B5%EF%BC%9A%E6%97%B6%E9%99%90%E6%9B%B4%E9%9A%BE%E8%B5%B6%E4%B8%8A%22%5D%0A%20%20LIQ%20--%3E%20TIGHT%0A%20%20BUF%5B%22%E6%97%A5%E7%BB%88%E9%A2%84%E7%AE%97%E9%87%8C%E7%9A%84%E7%BC%93%E5%86%B2%20B%22%5D%20-.-%3E%7C%22%E6%8F%90%E5%89%8D%E5%90%B8%E6%94%B6%E7%BC%BA%E5%8F%A3%22%7C%20GAP%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">保证金与结算保证金是两笔占用：前者跟杠杆与额度有关（券商给的），后者跟交收周期与净额有关（CCP 收的）。周期从 T+2 压到 T+1 改的是后者，前一项不会自动少——把两笔混在一个科目里，压缩周期后预算会两头都算错。</span></p><p><span class="marginnote">把预算不等式代入数字：某账户初始保证金 \\(\\mathrm{IM}=200\\) 万、变动保证金 \\(\\mathrm{VM}=50\\) 万、缓冲 \\(B=30\\) 万，则可用资金 \\(C\\) 至少要 280 万；若情景预测明天参数上调把 \\(\\mathrm{IM}\\) 推到 260 万，缺口 50 万今天就该走预划款——等追缴通知到了再筹，钱多半还在路上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写机构侧的预算与流程，不重写 CCP 内部的违约瀑布与净额法律安排，见<a href="/quant/ccp-default-waterfall">中央对手方与违约瀑布</a>；各产品保证金的具体公式以交易所、清算所与券商文本为准，SPAN 类情景扫描的参数不在本课复刻。强平次序的预写不改变一条边界：运营保证「补得上、平得有序」，不保证不平——方向性亏损与保证金不足是两件事，前者是研究的问题，后者才是本课的对象。</p><p><span class="marginnote">初学者容易以为强平是因为「亏了钱」。实际上方向亏损与保证金不足是两件事：一个几乎不亏但高杠杆的组合，也可能在波动率跳升、保证金参数上调时被追缴甚至强平；混同两者，会把运营风控问题错当成择股问题去修。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保证金是被每日重估的随机变量，按预算科目管理，逐账户对平口径。</li><li>预测用参数日历做情景，不用均值外推；盯市的顺周期性让追缴与流动性紧张重合。</li><li>预算不等式 \\(\\mathrm{IM}_t+\\mathrm{VM}_t+B_t\\le C_t\\) 配两道预警线，给划款链路留时间。</li><li>追缴路径与强平次序预写；交收失败是常态状态变量，当天进对账差异。</li><li>出处：据逐日盯市、SPAN 类情景保证金与 CCP 违约瀑布公开机制整理；对照<a href="/quant/ccp-default-waterfall">中央对手方与违约瀑布</a>、<a href="/quant/us-t1-settlement">美国 T+1 结算</a>。</li></ul>',7))])}const c=l(i,[["render",p]]);export{f as __pageData,c as default};
